import { closeSync, openSync, readSync } from 'node:fs';

const MARKER_LINES = 5;
const HEADER_LINES = 200;
const HEAD_BYTES = 16 * 1024;
const GENERATOR_MARKER = new RegExp(
  [
    '@generated\\b',
    '\\bDO NOT EDIT\\b',
    '<auto-generated',
    '\\bauto-?generated\\b',
    '\\bThis file (?:is|was|has been) (?:automatically )?generated\\b',
  ].join('|'),
  'iu',
);
const GENERATOR_HEADERS = [
  /^Generated by the protocol buffer compiler\. {1,2}DO NOT EDIT!/u,
  /^Generated by the gRPC Python protocol compiler plugin\. DO NOT EDIT!/u,
  /^generated by datamodel-codegen:/u,
  /\b(?:auto generated|Generated) by OpenAPI Generator \(https:\/\/openapi-generator\.tech\)/u,
  /^Code generated by \S[^\n]*\. DO NOT EDIT\.$/u,
  /^@generated by protoc-gen-\S/u,
  /^Autogenerated by Thrift Compiler \(/u,
  /^This file is generated by jOOQ\.$/u,
  /^Code generated by Wire protocol buffer compiler, do not edit\.$/u,
  /^Autogenerated by Avro$/u,
  /^Generated from \S+\.g4 by ANTLR \d/u,
  /^This file was generated by the (?:Eclipse Implementation of JAXB|JavaTM Architecture for XML Binding)\b/u,
  /\bauto generated by the swagger code generator program\b/u,
  /^(?:AUTO-GENERATED FILE\.|Automatically generated file\.)\s+DO NOT MODIFY\.?$/u,
];
const GENERATOR_ANNOTATION = new RegExp(
  String.raw`^[ \t]*@(?:(?:javax|jakarta)\.annotation\.(?:processing\.)?)?Generated\s*\([\s{]*(?:value\s*=[\s{]*)?"(?:` +
    [
      String.raw`org\.mapstruct\.ap\.`,
      String.raw`dagger\.`,
      String.raw`com\.google\.auto\.`,
      String.raw`org\.immutables\.`,
      String.raw`com\.querydsl\.`,
      String.raw`by gRPC proto compiler`,
      String.raw`org\.hibernate\.jpamodelgen\.`,
      String.raw`org\.openapitools\.codegen\.`,
      String.raw`io\.swagger\.codegen`,
      String.raw`org\.jooq\.codegen\.`,
      String.raw`com\.squareup\.`,
      String.raw`io\.micronaut\.`,
      String.raw`androidx\.room\.`,
    ].join('|') +
    ')',
  'mu',
);
const LINE_COMMENT = /^(?:#|\/\/)/u;
const BLOCK_START = '/*';
const BLOCK_END = '*/';
const DOCSTRING_START = /^[rRuU]?("""|''')/u;
const COMMENT_SYNTAX = /^(?:#!?|\/\/+|\/?\*+)\s*/u;

export function hasGeneratorMarker(text) {
  return GENERATOR_MARKER.test(text.split('\n', MARKER_LINES).join('\n'));
}

function content(line) {
  return line.replace(COMMENT_SYNTAX, '').trim();
}

function untilClosing(state, line) {
  const end = line.indexOf(state.closing);
  state.header.push(content(end === -1 ? line : line.slice(0, end)));
  state.closing = end === -1 ? state.closing : undefined;
}

function opening(state, line, { start, closing }) {
  state.closing = closing;
  untilClosing(state, line.slice(start));
}

function headerStep(state, line) {
  if (state.closing !== undefined) {
    untilClosing(state, line);
    return true;
  }
  if (line === '' || LINE_COMMENT.test(line)) {
    state.header.push(content(line));
    return true;
  }
  if (line.startsWith(BLOCK_START)) {
    opening(state, line, { start: BLOCK_START.length, closing: BLOCK_END });
    return true;
  }
  const docstring = state.docstring ? undefined : (DOCSTRING_START.exec(line) ?? undefined);
  if (docstring !== undefined) {
    state.docstring = true;
    opening(state, line, { start: docstring[0].length, closing: docstring[1] });
    return true;
  }
  return false;
}

/** The text of a file's leading comments and module docstring, one entry per line. */
export function headerLines(text) {
  const state = { header: [], closing: undefined, docstring: false };
  for (const line of text.split(/\r?\n/u, HEADER_LINES)) {
    if (!headerStep(state, line.trim())) {
      break;
    }
  }
  return state.header.filter(Boolean);
}

/** True when the leading comments or docstring carry the header a known code generator writes. */
export function hasGeneratorHeader(text) {
  return headerLines(text).some((line) => GENERATOR_HEADERS.some((header) => header.test(line)));
}

export function hasGeneratorAnnotation(text) {
  return GENERATOR_ANNOTATION.test(text);
}

export function readFileHead(absolute) {
  const descriptor = openSync(absolute, 'r');
  try {
    const head = Buffer.alloc(HEAD_BYTES);
    const read = readSync(descriptor, head, 0, HEAD_BYTES, 0);
    return head.subarray(0, read).toString('utf8');
  } finally {
    closeSync(descriptor);
  }
}

export function fileHasGeneratorHeader(absolute) {
  return hasGeneratorHeader(readFileHead(absolute));
}
